={
  "model": "llama3.2",
  "stream": false,
  "messages": [
    {
      "role": "user",
      "content": "You are a Shakespeare expert. The user requested information about the play '{{ $json.play_name }}'. They want: {{ $json.output_type === 'Key Characters' ? 'a list of key characters with brief descriptions' : 'human-centric themes (love, betrayal, ambition, etc.) with short explanations' }}.\n\nReturn ONLY valid JSON with this structure: { \"play\": \"<play name>\", \"requestType\": \"characters\" or \"themes\", \"title\": \"<descriptive title>\", \"items\": [{ \"name\": \"<name>\", \"description\": \"<brief description>\" }], \"summary\": \"<one sentence overview>\" }"
