parameters.jsCode:
const items = $input.all().map((i) => i.json || {});

const form = items.find(
  (i) => i.play_name || i.output_type || i.email || i['Shakespeare Play'] || i['What would you like?'] || i['Your email address'],
) || {};

const ollama = items.find((i) => i.message?.content || i.response || i.model || i.created_at) || {};

const play_name = form.play_name || form['Shakespeare Play'] || '';
const output_type = form.output_type || form['What would you like?'] || 'Key Characters';
const email = form.email || form['Your email address'] || '';
const output_type_value = output_type === 'Human-centric Themes' ? 'themes' : 'characters';

let json_content;
let parsed_content;
try {
  const raw = ollama.message?.content || ollama.response || JSON.stringify(ollama);
  const match = typeof raw === 'string' ? raw.match(/\{[\s\S]*\}/) : null;
  parsed_content = match
    ? JSON.parse(match[0])
    : { play: play_name, requestType: output_type_value, raw };
  json_content = JSON.stringify(parsed_content, null, 2);
} catch (e) {
  parsed_content = {
    play: play_name,
    requestType: output_type_value,
    error: 'Parse failed',
    raw: ollama.message?.content || ollama.response || null,
  };
  json_content = JSON.stringify(parsed_content, null, 2);
}

const escapeHtml = (v) => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;')
  .replace(/'/g, '&#39;');

const title = parsed_content.title || `${output_type} for ${play_name}`;
const summary = parsed_content.summary || '';
const itemsList = Array.isArray(parsed_content.items) ? parsed_content.items : [];

const tableRows = itemsList.length
  ? itemsList.map((item) => `<tr><td style=\"padding:8px;border:1px solid #ddd;vertical-align:top;\">${escapeHtml(item.name)}</td><td style=\"padding:8px;border:1px solid #ddd;vertical-align:top;\">${escapeHtml(item.description)}</td></tr>`).join('')
  : `<tr><td colspan=\"2\" style=\"padding:8px;border:1px solid #ddd;\">No rows returned</td></tr>`;

const html_content = `
  <div style="font-family:Arial,sans-serif;line-height:1.5;color:#1f2937;">
    <h2 style="margin-bottom:8px;">${escapeHtml(title)}</h2>
    <p style="margin:0 0 12px;"><strong>Play:</strong> ${escapeHtml(play_name)}<br/><strong>Request:</strong> ${escapeHtml(output_type)}</p>
    ${summary ? `<p style="margin:0 0 14px;"><strong>Summary:</strong> ${escapeHtml(summary)}</p>` : ''}
    <table style="border-collapse:collapse;width:100%;max-width:760px;">
      <thead>
        <tr>
          <th style="text-align:left;padding:8px;border:1px solid #ddd;background:#f3f4f6;">Name</th>
          <th style="text-align:left;padding:8px;border:1px solid #ddd;background:#f3f4f6;">Description</th>
        </tr>
      </thead>
      <tbody>${tableRows}</tbody>
    </table>
  </div>
`.trim();

return {
  json: {
    play_name,
    output_type,
    output_type_value,
    email,
    json_content,
    html_content,
  },
};
